import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.net.http.HttpTimeoutException;
import java.time.Duration;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.atomic.AtomicInteger;

public class ClientDemo {
    static final AtomicInteger flakyCalls = new AtomicInteger();

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 8081), 0);
        server.setExecutor(Executors.newVirtualThreadPerTaskExecutor());
        server.createContext("/ok", ex -> reply(ex, 200, "ok"));
        server.createContext("/slow", ex -> {
            try { Thread.sleep(2000); } catch (InterruptedException ignored) { }
            reply(ex, 200, "late");
        });
        server.createContext("/flaky", ex -> {
            int n = flakyCalls.incrementAndGet();
            reply(ex, n <= 2 ? 503 : 200, n <= 2 ? "unavailable" : "recovered");
        });
        server.start();

        HttpClient client = HttpClient.newBuilder()
                .version(HttpClient.Version.HTTP_1_1)
                .connectTimeout(Duration.ofSeconds(1))
                .build();

        // 1. normal call
        HttpResponse<String> r = send(client, "/ok", Duration.ofSeconds(1));
        System.out.println("ok     -> " + r.statusCode() + " " + r.body()
                + " version=" + r.version());

        // 2. request timeout
        long t0 = System.nanoTime();
        try {
            send(client, "/slow", Duration.ofMillis(500));
        } catch (HttpTimeoutException e) {
            long ms = (System.nanoTime() - t0) / 1_000_000;
            System.out.println("slow   -> " + e.getClass().getSimpleName() + " after ~"
                    + (ms / 100) * 100 + " ms");
        }

        // 3. retry with exponential backoff and jitter (idempotent GET only)
        long cap = 100;
        for (int attempt = 1; attempt <= 4; attempt++) {
            r = send(client, "/flaky", Duration.ofSeconds(1));
            System.out.println("flaky  -> attempt " + attempt + " status " + r.statusCode());
            if (r.statusCode() < 500) {
                break;
            }
            long sleep = ThreadLocalRandom.current().nextLong(cap / 2, cap + 1);
            System.out.println("          waiting " + sleep + " ms before the next attempt");
            Thread.sleep(sleep);
            cap *= 2;
        }

        // 4. connection refused (nothing listens on 8082)
        try {
            client.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:8082/")).build(),
                    HttpResponse.BodyHandlers.ofString());
        } catch (IOException e) {
            System.out.println("refused-> " + e.getClass().getName());
        }
        server.stop(0);
    }

    static HttpResponse<String> send(HttpClient c, String path, Duration timeout) throws Exception {
        HttpRequest req = HttpRequest.newBuilder(URI.create("http://127.0.0.1:8081" + path))
                .timeout(timeout).GET().build();
        return c.send(req, HttpResponse.BodyHandlers.ofString());
    }

    static void reply(HttpExchange ex, int code, String body) throws IOException {
        byte[] b = body.getBytes();
        ex.sendResponseHeaders(code, b.length);
        ex.getResponseBody().write(b);
        ex.close();
    }
}

// RestClient on the JDK HttpClient: connect timeout on the client, read timeout on the factory
HttpClient jdk = HttpClient.newBuilder()
        .connectTimeout(Duration.ofSeconds(2))
        .build();
JdkClientHttpRequestFactory factory = new JdkClientHttpRequestFactory(jdk);
factory.setReadTimeout(Duration.ofSeconds(5));
RestClient rest = RestClient.builder()
        .baseUrl("http://orders:8080")
        .requestFactory(factory)
        .build();

// WebClient on Reactor Netty: bounded pool, bounded wait for a connection, response timeout
ConnectionProvider pool = ConnectionProvider.builder("orders")
        .maxConnections(100)
        .pendingAcquireTimeout(Duration.ofSeconds(2))
        .maxIdleTime(Duration.ofSeconds(20))
        .maxLifeTime(Duration.ofMinutes(5))
        .build();
reactor.netty.http.client.HttpClient netty = reactor.netty.http.client.HttpClient.create(pool)
        .option(ChannelOption.CONNECT_TIMEOUT_MILLIS, 2000)
        .responseTimeout(Duration.ofSeconds(5));
WebClient web = WebClient.builder()
        .clientConnector(new ReactorClientHttpConnector(netty))
        .build();

import com.sun.net.httpserver.HttpServer;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class LoadTest {
    public static void main(String[] args) throws Exception {
        Set<Integer> clientPorts = ConcurrentHashMap.newKeySet();
        HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 8083), 128);
        server.setExecutor(Executors.newFixedThreadPool(4));   // 4 workers, like a small Tomcat
        server.createContext("/work", ex -> {
            clientPorts.add(ex.getRemoteAddress().getPort());
            try { Thread.sleep(50); } catch (InterruptedException ignored) { }
            byte[] b = "done".getBytes();
            ex.sendResponseHeaders(200, b.length);
            ex.getResponseBody().write(b);
            ex.close();
        });
        server.start();
        for (int concurrency : new int[] {1, 4, 16, 64}) {
            clientPorts.clear();
            run(concurrency, 200, clientPorts);
        }
        server.stop(0); System.exit(0);
    }

    static void run(int concurrency, int total, Set<Integer> ports) throws Exception {
        HttpClient client = HttpClient.newHttpClient();
        HttpRequest req = HttpRequest.newBuilder(URI.create("http://127.0.0.1:8083/work")).build();
        List<Long> lat = Collections.synchronizedList(new ArrayList<>());
        long start = System.nanoTime();
        try (ExecutorService pool = Executors.newFixedThreadPool(concurrency)) {
            List<Future<?>> fs = new ArrayList<>();
            for (int i = 0; i < total; i++) {
                fs.add(pool.submit(() -> {
                    long t = System.nanoTime();
                    client.send(req, HttpResponse.BodyHandlers.discarding());
                    lat.add((System.nanoTime() - t) / 1_000_000);
                    return null;
                }));
            }
            for (Future<?> f : fs) f.get();
        }
        double secs = (System.nanoTime() - start) / 1e9;
        List<Long> s = new ArrayList<>(lat);
        Collections.sort(s);
        long p50 = s.get(s.size() / 2);
        long p99 = s.get((int) (s.size() * 0.99) - 1);
        System.out.printf("concurrency=%2d  req/s=%6.1f  p50=%4d ms  p99=%4d ms  connections=%d%n",
                concurrency, total / secs, p50, p99, ports.size());
    }
}

import java.io.IOException;
