public class FdLeak {
    public static void main(String[] args) throws Exception {
        try (ServerSocket server = new ServerSocket(9100, 50, InetAddress.getLoopbackAddress())) {
            Thread acceptor = Thread.startVirtualThread(() -> {
                try { while (true) { server.accept(); } } catch (IOException ignored) { }
            });
            List<Socket> leaked = new ArrayList<>();
            try {
                while (true) {
                    leaked.add(new Socket(InetAddress.getLoopbackAddress(), 9100));
                }
            } catch (IOException e) {
                System.out.println("opened " + leaked.size() + " client sockets, then: " + e);
            }
        }
    }
}

import collections
NAMES = {"01": "ESTABLISHED", "02": "SYN_SENT", "03": "SYN_RECV", "04": "FIN_WAIT1",
         "05": "FIN_WAIT2", "06": "TIME_WAIT", "07": "CLOSE", "08": "CLOSE_WAIT",
         "09": "LAST_ACK", "0A": "LISTEN", "0B": "CLOSING"}
count = collections.Counter()
for f in ("/proc/net/tcp", "/proc/net/tcp6"):
    try:
        for line in open(f).read().splitlines()[1:]:
            count[NAMES.get(line.split()[3], "?")] += 1
    except OSError:
        pass
for state, n in sorted(count.items()):
    print(f"{state:12s} {n}")

import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.net.http.HttpTimeoutException;
import java.time.Duration;

public class Gateway {
    public static void main(String[] args) throws Exception {
        HttpClient up = HttpClient.newBuilder().connectTimeout(Duration.ofMillis(500)).build();
        HttpServer gw = HttpServer.create(new InetSocketAddress("127.0.0.1", 9300), 0);
        gw.createContext("/", ex -> {
            int port = ex.getRequestURI().getPath().equals("/down") ? 9399 : 9301;
            int code;
            try {
                HttpRequest r = HttpRequest.newBuilder(URI.create("http://127.0.0.1:" + port + "/"))
                        .timeout(Duration.ofSeconds(1)).build();
                code = up.send(r, HttpResponse.BodyHandlers.discarding()).statusCode();
            } catch (HttpTimeoutException e) {
                code = 504;                       // upstream accepted but did not answer in time
            } catch (IOException e) {
                code = 502;                       // upstream refused or reset the connection
            } catch (InterruptedException e) {
                code = 503;
            }
            ex.sendResponseHeaders(code, -1);
            ex.close();
        });
        gw.start();
        HttpServer slow = HttpServer.create(new InetSocketAddress("127.0.0.1", 9301), 0);
        slow.createContext("/", ex -> {
            try { Thread.sleep(3000); } catch (InterruptedException ignored) { }
            ex.sendResponseHeaders(200, -1);
            ex.close();
        });
        slow.start();
    }
}

import java.io.IOException;
import java.net.InetAddress;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.ArrayList;
import java.util.List;

public class Churn {
    public static void main(String[] args) throws Exception {
        InetAddress lo = InetAddress.getLoopbackAddress();
        try (ServerSocket server = new ServerSocket(9400, 100, lo)) {
            List<Socket> leaked = new ArrayList<>();
            Thread srv = Thread.startVirtualThread(() -> {
                try {
                    while (true) {
                        Socket s = server.accept();
                        s.getInputStream().read();           // returns -1 when the client closes
                        if (leaked.size() < 20) leaked.add(s); // BUG: never closed -> CLOSE_WAIT
                        else s.close();
                    }
                } catch (IOException ignored) { }
            });
            for (int i = 0; i < 100; i++) {                   // 100 short-lived connections
                try (Socket c = new Socket(lo, 9400)) { c.getOutputStream().write(1); }
            }
            Thread.sleep(500);
            new ProcessBuilder("python3", "tcpstates.py").inheritIO().start().waitFor();
        }
    }
}

import java.util.ArrayList;
import java.util.List;

public class Verify {
    public static void main(String[] args) {
        // Problem 1 and 2: store-and-forward delay
        double bits = 1500 * 8;
        double[] rate = {100e6, 10e6, 100e6};
        double[] dist = {2_000, 1_000_000, 2_000};
        double tx = 0, prop = 0;
        for (int i = 0; i < 3; i++) {
            tx += bits / rate[i];
            prop += dist[i] / 2e8;
        }
        System.out.printf("P1 transmission %.2f ms, propagation %.2f ms, total %.2f ms%n",
                tx * 1e3, prop * 1e3, (tx + prop) * 1e3);
        double last = (tx + prop) + 2 * (bits / 10e6);
        System.out.printf("P2 third packet arrives at %.2f ms; 4 MB file: %.1f s%n",
                last * 1e3, 32e6 / 5e6);

        // Problem 3: bandwidth-delay product
        double bdp = 100e6 * 0.080 / 8;
        double cap = 65535 * 8 / 0.080;
        int shift = (int) Math.ceil(Math.log(bdp / 65535) / Math.log(2));
        System.out.printf("P3 BDP %.0f bytes, 64 KiB window limit %.2f Mbit/s, window scale %d%n",
                bdp, cap / 1e6, shift);

        // Problem 6: RFC 6298 estimator
        double[] r = {100, 120, 90, 300};
        double srtt = r[0], rttvar = r[0] / 2;
        System.out.printf("P6 R=%.0f SRTT=%.3f RTTVAR=%.3f RTO=%.3f%n",
                r[0], srtt, rttvar, srtt + 4 * rttvar);
        for (int i = 1; i < r.length; i++) {
            rttvar = 0.75 * rttvar + 0.25 * Math.abs(srtt - r[i]);
            srtt = 0.875 * srtt + 0.125 * r[i];
            System.out.printf("P6 R=%.0f SRTT=%.3f RTTVAR=%.3f RTO=%.3f%n",
                    r[i], srtt, rttvar, srtt + 4 * rttvar);
        }

        // Problem 7: Reno window per round
        List<Integer> w = new ArrayList<>();
        int cwnd = 1, ssthresh = 16;
        for (int round = 0; round <= 8; round++) {
            w.add(cwnd);
            cwnd = cwnd < ssthresh ? Math.min(cwnd * 2, ssthresh) : cwnd + 1;
        }
        System.out.println("P7 rounds 0 to 8: " + w);

        // Problem 8: Internet checksum of an IPv4 header
        int[] hdr = {0x4500, 0x0073, 0x0000, 0x4000, 0x4011,
                     0x0000, 0xc0a8, 0x0001, 0xc0a8, 0x00c7};
        long sum = 0;
        for (int x : hdr) {
            sum += x;
        }
        System.out.printf("P8 raw sum 0x%x, ", sum);
        while ((sum >> 16) != 0) {
            sum = (sum & 0xffff) + (sum >> 16);
        }
        System.out.printf("folded 0x%x, checksum 0x%04x%n", sum, (~sum) & 0xffff);

        // Problem 12: Little's law
        System.out.printf("P12 connections %.0f, measured L/lambda %.2f s%n",
                200 * 0.12, 64 / 78.2);
    }
}
